app.post('/orders', async (req, res, next) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const { rows } = await client.query('SELECT available FROM stock WHERE id = $1 FOR UPDATE', [req.body.productId]);
    if (rows[0].available < req.body.qty) throw new Error('insufficient stock');
    await client.query('UPDATE stock SET available = available - $1 WHERE id = $2', [req.body.qty, req.body.productId]);
    const order = await client.query('INSERT INTO orders (product_id, qty) VALUES ($1, $2) RETURNING id', [req.body.productId, req.body.qty]);
    await client.query('COMMIT');
    res.status(201).json({ id: order.rows[0].id });
  } catch (err) { await client.query('ROLLBACK'); next(err); }
  finally { client.release(); }
});
